package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;
public class WallRetentionTest{
 public static void main(String[] args)throws Exception{Path dir=Paths.get(args[0]);NativeWallHistory history=new NativeWallHistory(Files.readAllBytes(dir.resolve("original-wall-history.nwh")));int snapshots=0,cells=0,rejected=0;byte[] source=Files.readAllBytes(dir.resolve("original-wall-history.nwh"));int malformed=0;for(int at:new int[]{0,8,16,24,32,40,48,56,64,72,80,88,104}){byte[] bad=source.clone();ByteBuffer.wrap(bad).order(ByteOrder.LITTLE_ENDIAN).putLong(at,-1L);try{new NativeWallHistory(bad);throw new AssertionError("Malformed history accepted");}catch(IllegalArgumentException expectedFailure){malformed++;}}
 int eventAt=64;ByteBuffer parsed=ByteBuffer.wrap(source).order(ByteOrder.LITTLE_ENDIAN);while(parsed.getLong(eventAt)!=2)eventAt+=(int)parsed.getLong(eventAt+8);for(int relative:new int[]{8,16,24,32,48,56,64,72,80,88}){byte[] bad=source.clone();ByteBuffer.wrap(bad).order(ByteOrder.LITTLE_ENDIAN).putLong(eventAt+relative,-1L);try{new NativeWallHistory(bad);throw new AssertionError("Malformed event accepted");}catch(IllegalArgumentException expectedFailure){malformed++;}}for(int relative:new int[]{108,112,132,172}){byte[] bad=source.clone();ByteBuffer.wrap(bad).order(ByteOrder.LITTLE_ENDIAN).putInt(eventAt+relative,-1);try{new NativeWallHistory(bad);throw new AssertionError("Malformed command accepted");}catch(IllegalArgumentException expectedFailure){malformed++;}}byte[] input=source.clone();NativeWallHistory immutable=new NativeWallHistory(input);java.util.Arrays.fill(input,(byte)0);if(immutable.asset(0).get(31)!=history.asset(0).get(31)||immutable.count()!=history.count())throw new AssertionError("Mutable input");ByteBuffer asset=immutable.asset(0);if(!asset.isReadOnly())throw new AssertionError("Mutable asset");try{asset.put(0,(byte)0);throw new AssertionError("Asset write accepted");}catch(ReadOnlyBufferException expectedFailure){}try{history.samples(history.epoch+1,0,0);throw new AssertionError("Wrong epoch accepted");}catch(IllegalArgumentException expectedFailure){}try(DirectoryStream<Path> files=Files.newDirectoryStream(dir,"race-background-*.nrb")){for(Path file:files){NativeSceneSnapshot scene=new NativeBackgroundScene(Files.readAllBytes(file)).sky.scene;byte[][] proofs=new byte[scene.geometryCount()][];for(int i=0;i<proofs.length;i++)proofs[i]=Files.readAllBytes(dir.resolve("owner-"+scene.geometry(i).serial+".nrp"));NativeWallRetention retention=new NativeWallRetention(scene,history,proofs);if(!retention.belongsTo(scene))throw new AssertionError("Scene binding");byte[] expected=Files.readAllBytes(dir.resolve("wall-retention-"+scene.refresh+".ref"));ByteBuffer ref=ByteBuffer.wrap(expected).order(ByteOrder.LITTLE_ENDIAN);int count=ref.getInt();int[] actual=new int[38400];java.util.Arrays.fill(actual,-1);for(int i=0;i<retention.count();i++){NativeWallRetention.Draw draw=retention.draw(i);int[] records=draw.records();ByteBuffer texture=retention.texture(draw);for(int j=0;j<records.length;j+=3){int at=records[j+1]*240+records[j];if(actual[at]>=0)throw new AssertionError("Duplicate owner");actual[at]=texture.get(records[j+2])&255;}}int found=0;for(int v:actual)if(v>=0)found++;if(found!=count||found!=retention.cells())throw new AssertionError("Coverage");for(int i=0;i<count;i++){int cell=ref.getInt(),value=ref.getInt();if(actual[cell]!=value)throw new AssertionError("Retained source value");}cells+=count;snapshots++;byte[] valid=proofs[0];int selected=-1;for(int cell=0;cell<38400;cell++)if(valid[80+cell]==2){selected=cell;break;}if(selected<0)throw new AssertionError("No wall ownership");proofs[0]=valid.clone();ByteBuffer changed=ByteBuffer.wrap(proofs[0]).order(ByteOrder.LITTLE_ENDIAN);changed.putInt(38480+selected*4,changed.getInt(38480+selected*4)^1);try{new NativeWallRetention(scene,history,proofs);throw new AssertionError("Wrong writer accepted");}catch(IllegalArgumentException expectedFailure){rejected++;}proofs[0]=valid.clone();ByteBuffer.wrap(proofs[0]).order(ByteOrder.LITTLE_ENDIAN).putLong(24,scene.epoch+1);try{new NativeWallRetention(scene,history,proofs);throw new AssertionError("Wrong epoch accepted");}catch(IllegalArgumentException expectedFailure){rejected++;}}}int ownerChecks=0;try(DirectoryStream<Path> owners=Files.newDirectoryStream(dir,"owner-*.nrp")){for(Path file:owners){ByteBuffer proof=ByteBuffer.wrap(Files.readAllBytes(file)).order(ByteOrder.LITTLE_ENDIAN);NativeWallHistory.Samples samples=history.samples(proof.getLong(24),proof.getLong(48),(int)proof.getLong(64));byte[] full=Files.readAllBytes(dir.resolve("full-native-"+proof.getLong(32)+".bin"));for(int cell=0;cell<38400;cell++){if(proof.get(80+cell)!=2)continue;int assetId=samples.asset(cell),offset=samples.offset(cell);if(assetId<0||offset<0||history.asset(assetId).get(offset)!=full[cell]||samples.refresh(cell)!=Integer.toUnsignedLong(proof.getInt(38480+cell*4)))throw new AssertionError("Owner wall source mismatch");ownerChecks++;}}}if(snapshots!=9||ownerChecks!=299970||malformed!=27)throw new AssertionError("Incomplete fixtures");System.out.println("PASS_WALL_RETENTION snapshots="+snapshots+" owner_checks="+ownerChecks+" source_cells="+cells+" stale_rejected="+rejected+" malformed_rejected="+malformed);}
}
